using UnityEngine;using System.Collections.Generic;
public partial class DungeonPrototype {
 bool cityDataOnly,restoringCitySnapshot;DungeonSaveData cityModelSave;
 public void InitializeCityModel(DungeonSaveData value,Camera camera){cityDataOnly=true;CloseCityView();cityModelSave=JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(value));DungeonMapPersistence.Normalize(cityModelSave,DungeonMapSettings.Current);floorSnapshots=DungeonMapPersistence.Copy(cityModelSave.maps);interactionProgress=DungeonMapPersistence.Copy(cityModelSave.interactions);NormalizeInteractionProgress();view=camera;mapSettings=DungeonMapPersistence.Resolve(cityModelSave.activeMapId)??DigitalKingdomTransit.Map;
  if(mapSettings==null&&!string.IsNullOrEmpty(cityModelSave.city?.returnMap)){foreach(var candidate in Resources.LoadAll<DungeonMapSettings>(""))if(candidate.name==cityModelSave.city.returnMap){mapSettings=candidate;break;}}
  if(mapSettings==null)mapSettings=DungeonMapSettings.Current;map=(string[])mapSettings.rows.Clone();explored=new bool[map[0].Length,map.Length];visited=new bool[map[0].Length,map.Length];foreach(var c in cityModelSave.visited)if(Open(c))visited[c.x,c.y]=true;foreach(var c in cityModelSave.explored)if(c.x>=0&&c.y>=0&&c.x<map[0].Length&&c.y<map.Length)explored[c.x,c.y]=true;
  inventorySettings=DigitalKingdomTransit.Inventory!=null?DigitalKingdomTransit.Inventory:Resources.Load<CombatInventorySettings>("Combat/CombatInventorySettings");playerLevelSettings=DigitalKingdomTransit.Levels;characterSettings=DigitalKingdomTransit.Character!=null?DigitalKingdomTransit.Character:Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings");refugeSettings=RefugeSettings.Current;refuge=cityModelSave.refuge??new RefugeProgress();RestorePlayerProgression(cityModelSave.player);introductionCompleted=true;cityProgress=cityModelSave.city??new DigitalKingdomProgress();cityProgress.inCity=true;position=cityProgress.returnCell;heading=cityProgress.returnHeading;worldDialogue.Cancel();startMenuOpen=saveSlotsOpen=false;OpenCityView();
  if(!cityProgress.firstVisitCompleted)worldDialogue.Begin(City.firstVisit,()=>cityProgress.firstVisitCompleted=true);
 }
 DungeonSaveData CaptureCityModelSave(){cityModelSave.player=CapturePlayerProgression();cityModelSave.city=cityProgress;cityModelSave.refuge=refuge;cityModelSave.interactions=DungeonMapPersistence.Copy(interactionProgress);DungeonMapPersistence.StoreCurrent(cityModelSave);return JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(cityModelSave));}
 public void TickCityModel(){UpdateCityInput();}
 public void RenderCityModel(){DrawCity();}
}
